assert json.dumps(d, ensure_ascii=False, indent=1) == txt
R = d['_심볼예약']
B = '[2026-11-14 새 과 L43e]'
new = {
 '끈에 꿴 뚜껑 달린 빛깔 판지 상자 셋(주황 · 파랑 · 분홍) + 상자마다 위로 올라가는 같은 빛깔 화살': f'Hox(호메오) 유전자 — ① 체절 정체성 결정 ② 염색체 위 배열 순서 = 몸의 앞뒤 순서(동일선상성) 전용 {B} — L43e s2. 호메오박스(Hox)의 박스 = 상자 · 끈 한 가닥 = 염색체 · 끈에 꿴 차례 = 몸 상자의 차례(머리 주황 · 가슴 파랑 · 배 분홍) · 화살 = 「이 상자가 저 부위를 맡는다」. 끈 · 상자 · 화살은 모두 PIL(`L43e_pil.py` — 빛깔은 큰 초파리의 몸 상자에서 떠 옴). ⚠ 이 세계(s43)에서 끈이 지나가는 것은 모두 DNA 의 자리다 — 【끈이 지나가는 빨간 쇠 상자 + 경광등】(사일렌서)과 가르려고 빨강을 쓰지 않았고 뚜껑을 달았다 · 【끈이 지나가는 낮은 나무 응원 단】(인핸서)은 나무 · 앞면 동그라미. ⚠ 끈으로 묶은 소포(【끈으로 십자로 묶인 갈색 종이 소포】 택솔 · 【끈 묶은 소포 상자】 소포체)가 아니다 — 끈이 옆면의 구멍으로 드나든다(꿰였다).',
 '뚜껑 달린 상자 셋을 한 줄로 이어 지은 상자 초파리(주황 = 머리 · 파랑 = 가슴 · 분홍 = 배)': f'호메오 유전자가 정하는 몸 부위의 정체성 · 발생 패턴 전용 {B} — L43e s1(큰 것)과 이 그림의 모든 초파리. 상자의 빛깔 = 그 자리에 돋을 것: 주황 상자에는 붉은 눈 · 입 · 더듬이(머리) · 파랑 상자에는 다리 셋 · 날개 둘(가슴) · 분홍 상자에는 아무것도(배). 붉은 눈 = 초파리. 다리는 모든 초파리가 같은 꼴(엉덩이 → 무릎 → 발목 → 발끝)로 PIL 이 그린다(`legs()` — Gemini 의 곧은 막대 다리는 떼어 냈다). ⚠ 상자 몸은 이 그림(Hox)의 문법이다 — 계획의 「모건의 파리 방」(12 ~ 15장)에서는 눈 빛깔이 뜻이니 상자 빛깔에 뜻을 싣지 않는다. ⚠ 기차 · 객차로 그리지 않는다(【창 셋 달린 회청 객차】 = 코돈).',
 '큰 루페(둥근 확대경 · 놋쇠 테 · 나무 손잡이)를 얼굴 앞에 든 머리 센 흰 가운': f'루이스(초파리 돌연변이 연구로 호메오 유전자가 발생 패턴을 조절함을 발견) 전용 {B} — L43e s3. 루페 든 이 = 루이스. 돋보기는 덱에서 「들여다봄 · 관찰」 소품(L11c · L19a · 【둥근 화면 둘 … 큰 돋보기】)이라 뜻이 맞는다. ⚠ 【사람이 치켜든 주사기】(인슐린 — 흰 가운 대머리)와 가르게 머리숱 있는 센 머리 · 콧수염 없음 · 손에는 루페만(Gemini 구역 Z2 에서 바탕의 벗어진 정수리 · 콧수염을 고쳤다 — 알려진 인물을 닮지 않게).',
 '머리 자리의 상자가 파랑인 상자 초파리(파랑 · 파랑 · 분홍) — 더듬이 자리에 돋은 다리 둘 · 머리 위의 작은 날개 한 쌍': f'엉뚱한 부위에 다리 · 날개가 나는 호메오 돌연변이 → 특정 유전자가 체절 정체성을 결정 전용 {B} — L43e s4. 머리 자리에 가슴 빛깔(파랑) 상자가 놓이니 머리에 가슴의 것(다리 · 날개)이 돋는다(안테나페디아 꼴). 머리의 다리 둘은 몸 밑의 다리와 똑같은 관절 다리(PIL `legs()`) — Gemini 가 그린 굵은 검은 막대는 몸 밑의 곧은 다리와 꼴이 달라 「같은 다리」로 읽히지 않을 뻔했다 → 이 그림의 다리를 모두 한 꼴로 다시 그렸다. ⚠ 다른 초파리의 머리 상자 위에는 더듬이(끝에 둥근 알)만.',
 '아래 반만 남은 금 간 알껍데기 속에 뒤엉킨 작은 상자 셋(분홍 · 파랑 · 주황 — 차례가 거꾸로 · 가운데 구겨짐 · × 표)': f'호메오 돌연변이가 치명적인 까닭(부위의 정체성 · 배치가 바뀌어 심한 형태 이상 → 배아 치사) 전용 {B} — L43e s5. × = 죽음(L12f 의 「눈이 ×」 녹는 세균과 같은 표). 발치의 찌그러진 파랑 상자 둘(s6)과 한 자리 — 열성 동형접합 배아.',
 '발치의 파랑 작은 상자 한 짝 — 뚜껑 달린 성한 것 / 뚜껑이 꺾여 내려앉은 찌그러진 것(짝마다 그림자 하나)': f'대립유전자 두 벌 · 이형접합(성한 것 + 찌그러진 것) · 이형접합끼리 교배로 배아 치사를 피하면서 열성 표현형을 확인 전용 {B} — L43e s6. 부모 둘 = 성 + 찌(멀쩡히 산다 = 찌그러진 쪽이 열성) → 알 넷 = 성 · 성 / 성 · 찌 / 찌 · 성 / 찌 · 찌(1 : 2 : 1) — 찌그러진 것만 둘인 알만 깨져 죽었다. 상자 · 그림자 · 부모 → 알 화살은 PIL. ⚠ 찌그러진 것을 구긴 덩이로만 그리면 「구긴 종이 · 쓰레기」로 읽혔다(일치 검사 1 ~ 3회) → 뚜껑과 몸통이 보이는 「밟힌 상자」로. ⚠ 짝 사이를 띄우고 짝마다 그림자 하나를 함께 깐다(붙으면 어느 알의 것인지 헷갈린다 · 6 · 7회). ⚠ 교배에 하트를 그리지 않았다(【빨간 하트】 = 성 예약).',
 '꽃무늬 머릿수건을 쓴 속눈썹 긴 초파리가 붙든 점박이 알 + 알의 앞(왼쪽) 끝에 붙은 분홍 큰 코': f'비코이드 = 모체효과 유전자(어미가 알 앞쪽에 넣어 둔 mRNA 가 머리 쪽을 정한다) 전용 {B} — L43e s7. 비코(鼻 · 코) = 비코이드 · 어미가 붙여 준 것 = 모체효과 · 코 붙은 쪽 = 앞(큰 초파리의 머리 쪽과 같은 왼쪽). 곁의 알 하나도 왼쪽 끝에 코. ⚠ 처음 바탕은 코가 어미의 얼굴에 붙은 것처럼 그려졌다(알 — 코 — 얼굴) → 코는 알의 「어미에게서 먼 쪽 끝」에(Gemini 구역 Z4). ⚠ 코를 파랗게 칠하지 않는다(【코발트빛 파란 코】 = B12). ⚠ 젖병 · 유모차를 쓰지 않았다(【젖병 유모】 = 인히빈).',
 '꼬리지느러미로 선 생선 뼈 물고기가 내민 눈알 여섯 개들이 손잡이 판지 팩 + 맨 뒤 분홍 상자에 붉은 눈이 하나 더 달린 상자 초파리': f'척추동물 Pax-6 → 초파리에서 (초파리식) 눈 형성 유도 = 공통 조상의 같은 유전자 발현 기구 전용 {B} — L43e s8. 팩(pack) 6 = 팍스-6(paired box — 이것도 「상자」) · 등뼈가 훤한 물고기 = 척추동물 · 팩의 눈알은 파란 홍채(척추동물식)인데 돋은 눈은 머리의 것과 똑같은 붉은 눈(초파리식). 덧눈은 큰 초파리의 눈을 줄여 PIL 이 붙였다. ⚠ 실험의 생쥐를 그리지 않았다(【쥐 탈】 = Ras). ⚠ 덧눈을 다리 무릎에 달면 「붉은 공 · 열매」로 읽혔다(일치 검사 1회) → 머리처럼 상자 면에 달아야 눈으로 읽힌다(실제 실험에서는 다리 · 날개 · 더듬이에 생겼다 — 글에서 말한다). ⚠ 【돌 받침 위의 큰 눈알】(수정체 세포 표지 · L43d)과 가른다 — 이쪽은 팩에 든 작은 눈알 여섯.',
 '크림빛 바탕에 갈색 점이 박힌 알(초파리 알)': f'초파리의 알 · 배아 전용 {B} — L43e s5 · s6(세워 놓은 알 넷) · s7(옆으로 누운 알 둘). ⚠ 맨 흰 알로 그리지 않는다(【알 · 감 · 베】의 흰 알 = α) · 에그컵 · 리본 없음(FSH · 생식샘) · 갈색 큰 달걀(L43d 핵치환)과는 크기 · 점박이로 갈린다. 성한 알 셋은 한 알을 세 번 찍었다.',
}
for k, v in new.items():
    assert k not in R, k
    R[k] = v
def add(key, note):
    v = R[key]; assert isinstance(v, str), key
    R[key] = v + ' ' + note
