add('끈이 지나가는 낮은 나무 응원 단(앞면에 빛깔 동그라미 셋)', f'★ {B} L43e 는 단을 그리지 않았다 — 끈에 꿴 것은 뚜껑 달린 빛깔 상자 셋(Hox)뿐. 단 = 나무 + 앞면 동그라미 / 상자 = 빛깔 판지 + 뚜껑으로 가른다.')
add('금빛 짚끈 · 짚끈이 두 바퀴 감긴 나무 통', f'★ {B} L43e 끈 한 가닥 = 염색체 · 끈에 꿴 상자 셋 = 그 위에 차례로 놓인 Hox 유전자(왼쪽 그림 밖에서 와 오른쪽 끝에서 위로 꺾여 담 밑으로 — L43d 와 같은 길).')
add('돌 받침 위의 큰 눈알(파란 홍채)', f'★ {B} L43e s8 팩 속의 작은 눈알 여섯(파란 홍채) = Pax-6 — 받침 위의 큰 눈알 하나(수정체 세포 표지)와는 크기 · 개수 · 팩으로 갈린다.')
add('알 · 감 · 베 (α · γ · β)', f'★ {B} L43e 의 초파리 알은 갈색 점박이 크림빛 알이다(맨 흰 알 = α 와 가른다).')
add('쥐 탈', f'★ {B} L43e s8 Pax-6 실험의 생쥐도 그리지 않았다 — 「척추동물」을 등뼈가 훤한 생선 뼈 물고기로.')
add('코발트빛 파란 코', f'★ {B} L43e s7 알 끝에 붙은 큰 코(비코이드)는 분홍빛이다 — 사람 얼굴의 코가 아니라 알에 붙인 코.')
add('빨간 하트', f'★ {B} L43e s6 이형접합 부모의 교배에는 하트를 그리지 않았다(마주 선 둘 + 아래로 내려가는 회색 화살).')
add('둥근 화면 둘 — 크게 번진 빨간 얼룩 하나(+ 큰 돋보기) / 또렷한 체리 둘', f'★ {B} L43e s3 의 큰 루페(확대경)는 사람이 들고 들여다보는 관찰 소품이다(루페 든 이 = 루이스).')
add('사람이 치켜든 주사기', f'★ {B} L43e s3 의 흰 가운은 머리숱 있는 센 머리에 루페를 들었다(루이스) — 주사기 없음.')
add('조끼 단추의 줄과 개수', f'★ {B} L43e s8 팩 속 눈알 여섯은 두 줄로 셋씩이다(넷씩 두 줄 = CD8 이 아니다) · 끈에 꿴 상자는 셋.')
